def rle(s):
    if not s:
        return ""

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Append the last character and its count
    result.append(f"{current_char}{count}")

    return "".join(result)

def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return len(stack) == 0

def merge(a, b):
    result = []
    i, j = 0, 0

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1

    # Append remaining elements from list a, if any
    while i < len(a):
        result.append(a[i])
        i += 1

    # Append remaining elements from list b, if any
    while j < len(b):
        result.append(b[j])
        j += 1

    return result

def to_base(n, b):
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not (2 <= b <= 16):
        raise ValueError("b must be between 2 and 16 inclusive")

    digits = "0123456789abcdef"

    if n == 0:
        return "0"

    result = []
    while n > 0:
        remainder = n % b
        result.append(digits[remainder])
        n //= b

    # The digits were collected in reverse order (least significant first)
    return "".join(reversed(result))
